package main

// ❌ OLD: Pre-generics, you used interface{} everywhere. Every value is
// boxed into an interface (heap escape), every operation needs a type
// assertion (runtime checks), and the caller loses type safety — a
// wrong type only fails at runtime.
func Map(s []interface{}, f func(interface{}) interface{}) []interface{} {
	out := make([]interface{}, len(s))
	for i, v := range s {
		out[i] = f(v) // ❌ OLD: interface boxing + dynamic dispatch
	}
	return out
}

// Usage: Map([]interface{}{1,2,3}, func(v interface{}) interface{} {
//   return v.(int) * 2   // ❌ OLD: type assertion, runtime risk
// })

