package main

// ✅ NEW: True generics. The compiler instantiates Map per GC shape
// (e.g. one for int, one for string) — type-safe, no interface boxing,
// and the hot loops operate on concrete values.
func Map[T any](s []T, f func(T) T) []T {
	out := make([]T, len(s))
	for i, v := range s {
		out[i] = f(v) // ✅ NEW: no boxing, no assertions
	}
	return out
}

// ✅ NEW: type-safe usage — compiler rejects wrong types
// doubled := Map([]int{1, 2, 3}, func(v int) int { return v * 2 })
// names := Map([]string{"a", "b"}, strings.ToUpper)

